function validWordSquare(words) {
  // Pad every row to a full size x size grid (null = empty cell) and compare it with its transpose.
  const size = Math.max(words.length, ...words.map(w => w.length));
  const grid = [];
  for (let i = 0; i < size; i++) {
    const word = i < words.length ? words[i] : '';
    grid.push(Array.from({ length: size }, (_, j) => (j < word.length ? word[j] : null)));
  }
  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) if (grid[i][j] !== grid[j][i]) return false;
  }
  return true;
}

