function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const alphabet = large ? 'abcdefghij' : 'ab'.slice(0, int(1, 2)) + (rand() < 0.3 ? 'c' : '');
  const letter = () => alphabet[int(0, alphabet.length - 1)];
  // A shape that is symmetric: a staircase of row lengths joined with its own mirror image.
  const rows = large ? int(80, 100) : int(1, 5);
  const lens = [];
  let current = large ? int(rows - 5, 100) : int(1, 5);
  for (let i = 0; i < rows; i++) {
    lens.push(current);
    if (rand() < 0.4) current = Math.max(1, current - int(1, 2));
  }
  const side = Math.max(rows, lens[0]);
  const filled = (i, j) => (i < rows && j < lens[i]) || (j < rows && i < lens[j]);
  const grid = Array.from({ length: side }, () => []);
  for (let i = 0; i < side; i++) {
    for (let j = i; j < side; j++) {
      if (filled(i, j)) grid[i][j] = grid[j][i] = letter();
    }
  }
  const words = grid.map(row => row.join('')).filter(word => word.length > 0);
  // Half of the inputs get one small change that usually breaks the square.
  if (rand() < 0.5) {
    const mode = int(0, 4);
    const k = int(0, words.length - 1);
    if (mode === 0) {
      const j = int(0, words[k].length - 1);
      const others = 'abcz'.split('').filter(ch => ch !== words[k][j]);
      words[k] = words[k].slice(0, j) + others[int(0, others.length - 1)] + words[k].slice(j + 1);
    } else if (mode === 1 && words[k].length < (large ? 100 : 6)) words[k] += letter();
    else if (mode === 2 && words[k].length > 1) words[k] = words[k].slice(0, -1);
    else if (mode === 3 && words.length > 1) words.pop();
    else if (words.length < (large ? 100 : 6)) words.push(Array.from({ length: int(1, 3) }, letter).join(''));
  }
  return [words];
}
